import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"ru/cli/run.md","filePath":"ru/cli/run.md","lastUpdated":1784903584000}'),d={name:"ru/cli/run.md"};function l(o,a,s,n,h,c){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="назначение" tabindex="-1">Назначение <a class="header-anchor" href="#назначение" aria-label="Permalink to &quot;Назначение&quot;">​</a></h2><p>Запустить интерактивный <strong>TUI (Terminal User Interface)</strong> — обозреватель API. Это полноэкранное приложение для поиска, просмотра, изучения и вызова эндпоинтов API, не выходя из терминала.</p><h2 id="когда-использовать" tabindex="-1">Когда использовать <a class="header-anchor" href="#когда-использовать" aria-label="Permalink to &quot;Когда использовать&quot;">​</a></h2><ul><li>Вы хотите интерактивно исследовать свои API</li><li>Вам нужно найти конкретный эндпоинт по всем спецификациям</li><li>Вы хотите просмотреть иерархию спецификация → коллекция → тег → эндпоинт</li><li>Вы хотите протестировать вызов API перед настройкой MCP-сервера</li></ul><h2 id="синтаксис" tabindex="-1">Синтаксис <a class="header-anchor" href="#синтаксис" aria-label="Permalink to &quot;Синтаксис&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="аргументы" tabindex="-1">Аргументы <a class="header-anchor" href="#аргументы" aria-label="Permalink to &quot;Аргументы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Аргумент</th><th>Позиция</th><th>Обязательно</th><th>Описание</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>Нет</td><td>Директория рабочей области. Если не указан, разрешается по правилам разрешения пути.</td></tr></tbody></table><h2 id="флаги" tabindex="-1">Флаги <a class="header-anchor" href="#флаги" aria-label="Permalink to &quot;Флаги&quot;">​</a></h2><p>Нет.</p><h2 id="режимы" tabindex="-1">Режимы <a class="header-anchor" href="#режимы" aria-label="Permalink to &quot;Режимы&quot;">​</a></h2><h3 id="режим-поиска" tabindex="-1">Режим поиска <a class="header-anchor" href="#режим-поиска" aria-label="Permalink to &quot;Режим поиска&quot;">​</a></h3><p>Полнотекстовый поиск по всем эндпоинтам во всех спецификациях. Поддерживает фильтрацию по HTTP-методу, тегу и пути.</p><ul><li>Введите запрос для поиска по именам эндпоинтов, путям и описаниям</li><li>Фильтруйте результаты по методу (GET, POST, PUT, DELETE и т.д.)</li><li>Просматривайте детали эндпоинта одним нажатием клавиши</li></ul><h3 id="режим-обзора" tabindex="-1">Режим обзора <a class="header-anchor" href="#режим-обзора" aria-label="Permalink to &quot;Режим обзора&quot;">​</a></h3><p>Древовидная навигация по иерархии спецификаций:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Спецификация → Коллекция → Тег → Эндпоинт</span></span></code></pre></div><ul><li>Перемещайтесь по дереву для поиска конкретных эндпоинтов</li><li>Просматривайте детали эндпоинта (параметры, тело запроса, ответы)</li><li>Вызывайте API напрямую из TUI</li></ul><h2 id="навигация" tabindex="-1">Навигация <a class="header-anchor" href="#навигация" aria-label="Permalink to &quot;Навигация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Клавиша</th><th>Действие</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Перемещение вверх/вниз</td></tr><tr><td><code>Enter</code></td><td>Выбор или открытие</td></tr><tr><td><code>Esc</code></td><td>Назад</td></tr><tr><td><code>Tab</code></td><td>Переключение между режимами поиска и обзора</td></tr><tr><td><code>/</code></td><td>Фокус на поле поиска</td></tr><tr><td><code>q</code></td><td>Выход</td></tr></tbody></table><h2 id="проверка-после-команды" tabindex="-1">Проверка после команды <a class="header-anchor" href="#проверка-после-команды" aria-label="Permalink to &quot;Проверка после команды&quot;">​</a></h2><p>TUI загружает все спецификации из рабочей области. Если спецификация не загружается, в интерфейсе отображается сообщение об ошибке.</p><h2 id="нюансы" tabindex="-1">Нюансы <a class="header-anchor" href="#нюансы" aria-label="Permalink to &quot;Нюансы&quot;">​</a></h2><ul><li><strong>Автоинициализация:</strong> Если файл конфигурации не существует, <code>run</code> автоматически запускает мастер инициализации.</li><li><strong>Нет флагов:</strong> Команда <code>run</code> не имеет флагов — вся конфигурация берётся из рабочей области.</li><li><strong>Размер терминала:</strong> TUI требует терминал размером не менее 80×24 символов. Он может некорректно отображаться в очень маленьких терминалах.</li><li><strong>Зависимости:</strong> TUI использует Bubbletea. Он работает через SSH и в большинстве эмуляторов терминала.</li></ul>',25)])])}const b=t(d,[["render",l]]);export{p as __pageData,b as default};
